// Source of truth: this .ts file. archived.js is generated by `npm --prefix web run build:ts`.
// Archived screens (15/11, ordem do Gustavo: o cockpit é o único painel). Loaded as a classic script in <head>, it sends the
// visitor to cockpit.html before the old screen renders, keeping ?site= and the #hash. The page itself stays intact in
// the repo; ?archived=1 opens it as it was (see ARQUIVO.md).
export function archivedTarget(search: string, hash: string): string | null {
  return new URLSearchParams(search).get("archived") === "1" ? null : "cockpit.html" + search + hash;
}
if (typeof location !== "undefined") { const to = archivedTarget(location.search, location.hash); if (to && typeof location.replace === "function") location.replace(to); }
